#!/usr/bin/env python3
"""
Script to run Dijkstra algorithm and save results to file
"""

import json
import sys

def format_dijkstra_results(results):
    """Format Dijkstra results in the requested format"""
    formatted_lines = []

    if isinstance(results, dict) and 'data' in results:
        data = results['data']
        for item in data:
            if 'path' in item and 'costs' in item:
                path = item['path']
                costs = item['costs']
                formatted_lines.append(f'{path}: {costs}')
            elif 'nodeNames' in item and 'costs' in item:
                path = item['nodeNames']
                costs = item['costs']
                formatted_lines.append(f'{path}: {costs}')

    return '\n'.join(formatted_lines)

def main():
    print("This script would run the Dijkstra algorithm if we had direct MCP access")
    print("The results will be saved to dijkstra_arsenal_results.txt")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Script to capture Dijkstra results and format them
"""

import sys
import json

def format_dijkstra_output(results):
    """Format the results in the requested format"""
    output_lines = []

    # Handle different possible result formats
    if isinstance(results, dict):
        if 'data' in results:
            data = results['data']
        elif 'results' in results:
            data = results['results']
        else:
            data = results

        # Process each path result
        for i, item in enumerate(data, 1):
            if isinstance(item, dict):
                path = item.get('path', item.get('nodeNames', []))
                costs = item.get('costs', item.get('distances', []))

                if path and costs:
                    # Format as requested: ["Node1", "Node2", "Node3"]: [cost1, cost2, cost3]
                    path_str = str(path)
                    costs_str = str(costs)
                    line = f"{i:6d}→{path_str}: {costs_str}"
                    output_lines.append(line)

    return '\n'.join(output_lines)

if __name__ == "__main__":
    print("Ready to format Dijkstra results")

